<template>
  <div class="layout-px-spacing">
    <ul class="navbar-nav flex-row mt-2">
      <li>
        <div class="page-header">
          <nav class="breadcrumb-one" aria-label="breadcrumb">
            <ol class="breadcrumb">
              <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
              <li class="breadcrumb-item active" aria-current="page">
                <span>Subcontractors</span>
              </li>
            </ol>
          </nav>
        </div>
      </li>
    </ul>

<div class="my-4">
    <globalSearchField v-model:filterValue="filter" />
</div>

    <!-- Loading spinner -->
    <!-- Agreements list -->
    <div v-if="loading_spinner" v-html="loadingIndicator()"></div>

    <div v-else class="row">
      <div class="col-12">
        <div class="panel p-0">
          <div class="custom-table table3">
            <v-client-table :data="filteredData" :columns="agreementsColumns" :options="table_option">

              <template #title="props">
                <strong class="text-primary">{{ props.row.title }}</strong>
                <div class="small text-muted">{{ props.row.payment_term }}</div>
              </template>

              <template #rate="props">{{ formatNumber(props.row.rate) }}</template>

              <template #quantity="props">{{ formatNumber(props.row.quantity) }} {{ props.row.unit }}</template>
              <template #revised="props">{{ formatNumber(props.row.revised) }} {{ props.row.unit }}</template>
                   <template #archived="props">{{ formatNumber(props.row.archived) }} {{ props.row.unit }}</template>
                   <template #total="props">{{ formatNumber(props.row.total) }} {{ props.row.unit }}</template>
             
              <template #actions="props">
                <div class="d-flex justify-content-center align-items-center gap-2">

                 
                  <router-link :to="`/subcontractor/${props.row.id}`" title="Details" class="text-primary">
                   <i class="bi bi-eye fs-4"></i>
                  </router-link>

                  <a
                    v-if="!parseFloat(props.row.balance) <= 0 && user_permissions.includes('can_create_subcontractor_requisition')"
                    class="btn-icon-plain text-success"
                    title="Request"
                    data-bs-toggle="modal"
                    data-bs-target="#quantity-modal"
                    @click="viewDetails(props.row)"
                    
                  >
                     <i class="bi bi-plus-square fs-4"></i>
                  </a>

                    <a
                    
                    class="btn-icon-plain text-secondary"
                    title="Revise"
                    data-bs-toggle="modal"
                    data-bs-target="#revised-modal"
                    @click="viewDetails(props.row)"
                    v-if="user_permissions.includes('can_revise_subcontractor_quantity')"
                  >
                    

                  <i class="bi bi-pencil-square fs-4"></i>
                  </a>


                </div>
              </template>

            </v-client-table>
          </div>
        </div>
      </div>
    </div>

    <!-- Archived quantity modal -->
    <div
      class="modal fade mymodal"
      id="quantity-modal"
      data-bs-backdrop="false"
      data-bs-keyboard="false"
      tabindex="-1"
      aria-labelledby="editEngineeringModalLabel"
      aria-hidden="true"
    >
      <div class="modal-dialog modal-xl">
        <div class="modal-content">
          <div class="modal-header">
            <h1 class="modal-title fs-5" id="editEngineeringModalLabel">
              Subcontract Archived Quantity : {{ selectedAgreement?.subcontracted_to }}
              <span v-if="budget_item_description">
                 (Budget rate {{ formatNumber(budget_item_description.cost) }} and Budget quantity {{ budget_item_description.quantity }} {{  selectedAgreement?.unit }})
              </span>
            </h1>
            <button
              type="button"
              class="btn-close"
              data-bs-dismiss="modal"
              aria-label="Close"
              @click="closeEditModal()"
              id="close_modal"
            ></button>
          </div>

          <form @submit.prevent="updateArchivedQuantity">
            <div class="modal-body">
              <div class="row">
                <div class="col-md-6">
                  <label for="quantity">
                    Archived Quantity (Remaining:
                    {{
                      Math.max(
                        0,
                        selectedAgreement?.quantity -
                          selectedAgreement?.archived_quantity
                      ).toFixed(2)
                    }})
                  </label>
                  <input
                    type="number"
                    v-model="archived_quantity"
                    class="form-control"
                    placeholder="Enter Archived Quantity"
                    step="any"
                    required
                  />
                </div>

                <div class="col-md-6">
                  <label for="total" class="form-label"
                    >Total Expected Archived Quantity</label
                  >
                  <span class="form-control">{{
                    totalArchivedQuantity.toLocaleString()
                  }}</span>
                </div>
        <div class="col-md-12 mt-2" >
          <textarea class="form-control" placeholder="Enter Brief Description of the requisition" v-model="briefing" required></textarea>
        </div>
                <div 
        class="col-md-4 mb-3 ">
            <label class="form-label small">Select Requisition Type</label>
            <multiselect 
                v-model="requisition_type"
                :options="['budget','general']"
                placeholder="Select Requisition Type"
                :searchable="true"        
                :multiple="false"
                :required="true"
                :allow-empty="false"
            ></multiselect>
        </div>
        

                <div class="col-md-4" v-if="requisition_type === 'budget'">
                  <label class="form-label small">Select A Budget</label>
                  <multiselect
                    v-model="budget"
                    :options="budgets"
                    placeholder="Select A Budget"
                    :searchable="true"
                    label="name"
                    :allow-empty="false"
                  />
                </div>

                <div class="col-md-4" v-if="budget">
                  <label class="form-label small">Select An Item</label>
                  <multiselect
                    v-model="budget_item"
                    :options="budgetItems"
                    placeholder="Select An Item"
                    :searchable="true"
                    label="name"
                    :allow-empty="false"
                  />
                </div>

                <div class="col-md-12" v-if="budget_item">
                  <label class="form-label small">Select Description</label>
                  <multiselect
                    v-model="budget_item_description"
                    :options="budgetItemDescriptions"
                    placeholder="Select An Option"
                    :searchable="true"
                    label="name"
                    :allow-empty="false"
                  />
                </div>
                 <div class="col-md-4" v-if="budget_item_description || requisition_type === 'general'">
                  <label class="form-label small">Enter Quantity</label>
                  <input type="number" class="form-control" placeholder="Enter Quantity" v-model="quantity" step="any" required>
                </div>
                   <div class="col-md-4" v-if="budget_item_description || requisition_type === 'general'">
                  <label class="form-label small">Enter Rate</label>
                  <input type="number" class="form-control" placeholder="Enter Rate" v-model="rate" required>
                </div>
               <div class="col-md-12" v-if="budget_item_description || requisition_type === 'general'">
                  <label class="form-label small">Enter Description</label>
                  <input type="text" class="form-control" placeholder="Enter item Description" v-model="description" required>
                </div>

                <div class="col-md-12 col-lg-12 mb-2 text-end">
            <button 
                type="button" 
                class="btn btn-outline-success btn-sm mt-4"
                @click="pushItem()"
                v-if="requisition_type === 'budget'"
            >
                <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="feather feather-plus-square">
                    <rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect>
                    <line x1="12" y1="8" x2="12" y2="16"></line>
                    <line x1="8" y1="12" x2="16" y2="12"></line>
                </svg>
                Add Item
            </button>
        </div>
              </div>
            </div>
<!-- item table starts -->
   <div 
     v-if="requisition_type === 'budget'"
   class="row layout-top-spacing" style="max-height: 67vh; overflow-y: auto;">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <v-client-table :data="formRequisitionItems" :columns="itemsColumns"  >
                          <template #actions="props">
  <a href="javascript:void(0);" title="Delete" @click="pullItem(props.row.Sno)">
                            <svg
                                xmlns="http://www.w3.org/2000/svg"
                                width="20"
                                height="20"
                                viewBox="0 0 24 24"
                                fill="none"
                                stroke="currentColor"
                                stroke-width="1.5"
                                stroke-linecap="round"
                                stroke-linejoin="round"
                                class="text-danger"
                            >
                                <polyline points="3 6 5 6 21 6"></polyline>
                                <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
                            </svg>
                        </a>
                          </template> 
                        
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>
<!-- item table ends -->
            <div class="modal-footer">
              <button
                type="button"
                class="btn btn-secondary"
                data-bs-dismiss="modal"
                @click="closeEditModal"
              >
                Close
              </button>
             <button 
  type="submit" 
  class="btn btn-primary"
  :disabled="(formRequisitionItems2.length == 0 && requisition_type ==='budget') || loading_spinner || !requisition_type"
>
  <span
    v-if="loading_spinner"
    class="spinner-border spinner-border-sm text-white me-2"
    role="status"
  ></span>
  Save
</button>

            </div>
          </form>
        </div>
      </div>
    </div>

    <!-- revised quantity starts -->
      <div
      class="modal fade mymodal"
      id="revised-modal"
      data-bs-backdrop="false"
      data-bs-keyboard="false"
      tabindex="-1"
      aria-labelledby="editEngineeringModalLabel"
      aria-hidden="true"
    >
      <div class="modal-dialog modal-xl">
        <div class="modal-content">
          <div class="modal-header">
            <h1 class="modal-title fs-5" id="editEngineeringModalLabel">
              Subcontractor Revised Quantity {{ selectedAgreement?.item }} ( {{ selectedAgreement?.subcontracted_to }} )
             
            </h1>
            <button
              type="button"
              class="btn-close"
              data-bs-dismiss="modal"
              aria-label="Close"
              @click="closeEditModal()"
              id="close-revised"
            ></button>
          </div>

          <form @submit.prevent="updateRevisedQuantity()">
            <div class="modal-body">
              <div class="row">
                <div class="col-md-6">
                   <label class="form-label">Enter Revised Quantity</label>
                  <input
                    type="number"
                    v-model="revised_quantity"
                    class="form-control"
                    placeholder="Enter Revised Quantity"
                    step="any"
                    required
                    
                  />
                </div>

                 <div class="col-md-6">
                   <label class="form-label">Total New Quantity</label>
                  <label class="form-control">{{  (Number(selectedAgreement?.quantity)  + Number(selectedAgreement?.revised_quantity) + Number(revised_quantity)).toFixed(2)}}</label>
                </div>

                 <div class="col-md-12">
                   <label class="form-label">Enter Brief Description</label>
                   <input
                    type="text"
                    v-model="description"
                    class="form-control"
                    placeholder="Enter Brief description"
                    
                  />                
                </div>

              </div>
              
            </div>

            <div class="modal-footer">
              <button
                type="button"
                class="btn btn-secondary"
                data-bs-dismiss="modal"
                @click="closeEditModal"
              >
                Close
              </button>
             <button 
  type="submit" 
  class="btn btn-primary"
  :disabled="loading_spinner"
>
  <span
    v-if="loading_spinner"
    class="spinner-border spinner-border-sm text-white me-2"
    role="status"
  ></span>
  Save
</button>

            </div>
          </form>
        </div>
      </div>
    </div>
     <!-- revised quantity ends -->
  </div>
</template>



<script setup>
import { ref, onMounted, inject, watch, computed } from "vue";
import axios from "axios";
import { useMeta } from "@/composables/use-meta";
import Multiselect from "@suadelabs/vue3-multiselect";
import "@suadelabs/vue3-multiselect/dist/vue3-multiselect.css";
import { globalSearch } from "@/components/reusables/globalSearch";
import GlobalSearchField from "@/components/reusables/globalSearchField.vue";

const user_permissions = JSON.parse(localStorage.getItem('user')).permissions

useMeta({ title: "Subcontractors Agreements" });

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL,
});

const filter = ref("");

const filteredData = computed(() => {
  return globalSearch(agreements.value, filter.value);
});

const table_option = ref({
    perPage: 10,
    perPageValues: [10, 20, 50],
    skin: 'table table-hover table-striped',
    columnsClasses: { actions: 'actions text-center' },
    sortable: ['title', 'subcontracted_to', 'quantity', 'rate', 'cost', 'balance'],
    sortIcon: {
        base: 'sort-icon-none',
        up: 'sort-icon-asc',
        down: 'sort-icon-desc',
    },
    pagination: { nav: 'scroll', chunk: 5 },
    texts: {
        count: 'Showing {from} to {to} of {count}',
        filter: '',
        filterPlaceholder: 'Search...',
        limit: 'Results:',
    },
    resizableColumns: false,
    headings: {
        // title: 'Agreement',
        subcontracted_to: 'Subcontracted To',
        quantity: 'Quantity',
        rate: 'Rate',
        cost: 'Total Cost',
        payable: 'Payable',
        balance: 'Balance',
        archived_quantity: 'Archived Qty',
        actions: 'Actions',
    },
});

const agreementsColumns = ref([
    'SNo','agreement', 'subcontracted_to', 'quantity', 'revised', 'total','archived', 'rate', 'cost', 'payable', 'balance',  'actions'
]);


const loadingIndicator = inject("loadingIndicator");
const formatNumber = inject("formatNumber");
const showMessage = inject("showMessage");
const showError = inject("showError");
const itemsColumns = ref(['Sno', 'item','description','quantity','units','rate','cost','actions']);
const loading_spinner = ref(false);
const agreements = ref([]);
const selectedAgreement = ref(null);
const archived_quantity = ref(0);
const totalArchivedQuantity = ref(0);
const description = ref('');
const requisition_type = ref('');
const briefing = ref('');
const revised_quantity = ref('')
const quantity = ref('')
const i = ref(1)  
const formRequisitionItems = ref([])
const formRequisitionItems2 = ref([])
const rate = ref(4000)
const clearItemForm = ()=>{
    quantity.value = '',
    description.value = ''
    budget_item_description.value = ''
    budget_item.value = '',
    rate.value = ''
}
    const pushItem = () => {
        if(!quantity.value ){
            showError("Fill in all fields");
            return ;
        }

        if( (quantity.value * rate.value) > (( budget_item_description.value.quantity *  budget_item_description.value.cost ) - budget_item_description.value.used_cost )  ){
            showError("Exceeds available budget cost : "+formatNumber(( budget_item_description.value.quantity *  budget_item_description.value.cost ) - budget_item_description.value.used_cost ) );
            return ;
        }
    const agreement = selectedAgreement.value
    const payload = {
      Sno: i.value,
      item: requisition_type.value === 'budget' ? budget_item.value.name : 'Subcontractor for ' + agreement.item ,
      item_id: requisition_type.value === 'budget' ? budget_item_description.value.id : 0,
      quantity: quantity.value,
      beneficiary: agreement.subcontracted_to + '( '+ agreement.payment_number+' )',
      rate: formatNumber(rate.value),
      // remark: agreement.item + (description.value ? ' ('+ description.value + ')' : ''),
      remark: agreement.item + '( '+ description.value + ' )',
      description: requisition_type.value === 'budget' ? budget_item_description.value.name + (description.value ? ' ('+ description.value + ')' : '') : 'Subcontractor for ' + agreement.item ,
      units: requisition_type.value === 'budget' ?  budget_item_description.value.units : agreement.unit,
      cost : formatNumber(quantity.value *rate.value)
    };

    const payload2 = {
      Sno: i.value,
      item_id: requisition_type.value === 'budget' ? budget_item_description.value.id : 0,
      quantity: quantity.value,
      beneficiary: agreement.subcontracted_to + '( '+ agreement.payment_number+' )',
      rate: rate.value,
      remark: agreement.item ,
      description: requisition_type.value === 'budget' ? budget_item_description.value.name + (description.value ? ' ('+ description.value + ')' : '') : 'Subcontractor for ' + agreement.item ,
      units: requisition_type.value === 'budget' ?  budget_item_description.value.units : agreement.unit,
    };


    // Add Sno as index (1-based)
    i.value = i.value + 1;
    formRequisitionItems.value.push(payload);
    formRequisitionItems2.value.push(payload2);
    clearItemForm()
    }


    const pullItem = (sno) => {
    formRequisitionItems.value = formRequisitionItems.value.filter(item => item.Sno !== sno);
    formRequisitionItems2.value = formRequisitionItems2.value.filter(item => item.Sno !== sno);
    formRequisitionItems.value.forEach((item, idx) => {
        item.Sno = idx + 1;
    });
    formRequisitionItems2.value.forEach((item, idx) => {
        item.Sno = idx + 1;
    });
    i.value = formRequisitionItems.value.length + 1;
}

const updateRevisedQuantity = async ()=>{
   const payload = {
    revised_quantity: Number(
      Number(selectedAgreement.value?.revised_quantity || 0) +
      Number(revised_quantity.value || 0)
    ),
    description: `Revising agreement work from ${Number(selectedAgreement.value?.quantity || 0) + Number(selectedAgreement.value?.revised_quantity || 0)} to ${Number(selectedAgreement.value?.quantity || 0) + Number(selectedAgreement.value?.revised_quantity || 0) + Number(revised_quantity.value || 0)}${description.value ? ' - ' + description.value : ''}`,
    subcontractor_id : selectedAgreement.value.id,
    remarker_id : JSON.parse(localStorage.getItem("user")).id,
   }
   loading_spinner.value = true
   try{
    const response = await axiosInstance.put(`subcontractor-agreements/${selectedAgreement.value.id}`,payload)
    showMessage('Agreement Revised')
    closeEditModal()
    getAgreements()
   }catch(error){
    showError(error.message)
    console.log(error)
   }finally{
    loading_spinner.value = false
   }
}

const budgets = ref([]);
const budget = ref("");
const budgetItems = ref([]);
const budget_item = ref("");
const budgetItemDescriptions = ref([]);
const budget_item_description = ref("");

const viewDetails = (row) => {
  selectedAgreement.value = row;
  archived_quantity.value = null;
  totalArchivedQuantity.value = Number(row.archived_quantity || 0);
  getBudgets(row.project_id);
};

watch(archived_quantity, (newVal) => {
  if (selectedAgreement.value) {
    totalArchivedQuantity.value =
      Number(selectedAgreement.value.archived_quantity || 0) +
      Number(newVal || 0);
  }
});

const getAgreements = async () => {
  loading_spinner.value = true;
  try {
    const response = await axiosInstance.get("/subcontractor-agreements");
   agreements.value = response.data.map((item, index) => ({
  ...item,
  SNo: index + 1,
  revised:item.revised_quantity,
  total:item.total_quantity,
  subcontractor_agreement_id: item.id,
  project_id: item.project.id,
  project: item.project.short_name,
  agreement: item.project.short_name + ' - ' + item.item,   // new
  attachment: "https://bushman.ink/" + item.attachment,
  payment_term: item.payment_term.name,
  rate: item.rate,
  cost: formatNumber(item.total_quantity * item.rate),
  archived_quantity: item.payments.reduce((sum, p) => sum + (p.quantity/item.rate || 0), 0).toFixed(2),
  payable: formatNumber(item.payments.reduce((sum, p) => sum + (p.quantity || 0), 0)),
    archived: item.payments.reduce((sum, p) => sum + (p.quantity/item.rate || 0), 0).toFixed(2),
  balance: formatNumber((item.total_quantity * item.rate) - item.payments.reduce((sum, p) => sum + (p.quantity || 0), 0)),}
));
  } catch (error) {
    showError(error.message);
  } finally {
    loading_spinner.value = false;
  }
};

const getBudgets = async (id) => {
  const response = await axiosInstance.get(`budgets?project_id=${id}`);
  budgets.value = response.data.filter((b) => b.status === "closed");
};

watch(budget, (newVal) => {
  if (newVal) budgetItems.value = newVal.items;
});
watch(budget_item, (newVal) => {
  if (newVal) budgetItemDescriptions.value = newVal.descriptions;
});

const updateArchivedQuantity = async () => {
    if(!archived_quantity.value){
    showError('Enter Archived Quantity !')
    return ;
  }
  loading_spinner.value = true;
      const payload = {
        archived_quantity: totalArchivedQuantity.value,
      }
     try {
    const response = await axiosInstance.put(`/subcontractor-agreements/${selectedAgreement.value.id}`,payload);
    if (response.status === 200) {
      await registerRequisition(selectedAgreement.value);
      document.getElementById("close_modal").click();
      await getAgreements();
      closeEditModal();
    } else {
      showError(error.message);
    }
  } catch (error) {
    showError(error.message);
  } finally {
    loading_spinner.value = false;
  }
};

const registerRequisition = async () => {
  if(requisition_type.value === 'general'){
      formRequisitionItems2.value =  [{
      item_id: requisition_type.value === 'budget' ? budget_item_description.value.id : 0,
      quantity: archived_quantity.value,
      beneficiary:selectedAgreement.value.subcontracted_to + '( '+ selectedAgreement.value.payment_number+' )',
      rate: selectedAgreement.value.rate,
      remark: selectedAgreement.value.item,
      description: requisition_type.value === 'budget' ? budget_item_description.value.name : 'Subcontractor for ' + selectedAgreement.value.item ,
      units: selectedAgreement.value.unit,
    }]
  }
  const formData = new FormData();

  formData.append(
    "requisition",
    JSON.stringify({
      date: new Date().toISOString().split("T")[0],
      description: briefing.value,
      project_id: selectedAgreement.value.project_id,
      required_date: new Date().toISOString().split("T")[0],
      requester_id: JSON.parse(localStorage.getItem("user")).id,
      beneficiary: selectedAgreement.value.subcontracted_to,
      subcontractor_agreement_id: selectedAgreement.value.id,
      approval_group_id: 8,
    })
  );

  formData.append(
    "type",
    JSON.stringify({
      name: requisition_type.value,
      item_id: requisition_type.value === 'budget' ? budget.value.id : 0,
    })
  );

    formData.append("items", JSON.stringify(formRequisitionItems2.value));
 
  try {
    await axiosInstance.post("create-requisition", formData, {
      headers: { "Content-Type": "multipart/form-data" },
    });
    showMessage("Requisition created successfully");
  } catch (error) {
    showError(error.message);
    console.log(error)
  }
};

const closeEditModal = () => {
  requisition_type.value = '';
  briefing.value = '';
  archived_quantity.value = 0;
  totalArchivedQuantity.value = 0;
  selectedAgreement.value = null;
  budget.value = "";
  budget_item.value = "";
  budget_item_description.value = "";
  budgetItems.value = [];
  budgetItemDescriptions.value = [];
  revised_quantity.value = ''
  formRequisitionItems.value = []
  formRequisitionItems2.value = []
  document.getElementById('close-revised').click()
  clearItemForm()
};

onMounted(() => {
  getAgreements();
});
</script>
